// Initialize velocities from Maxwell-Boltzmann distribution
std::random_device rd;
std::mt19937 gen(rd());
const double kB = 1.0; // Boltzmann constant (assuming units where kB=1)
double totalMass = 0.0;
vec3 comVelocity(0.0, 0.0, 0.0);

for (std::size_t i = 0; i < velocities.size(); ++i) {
    double stddev = std::sqrt(kB * temperature / masses[i]);
    std::normal_distribution<double> dist(0.0, stddev);

    velocities[i].x = dist(gen);
    velocities[i].y = dist(gen);
    velocities[i].z = dist(gen);

    // Calculate center of mass velocity components
    comVelocity += velocities[i] * masses[i];
    totalMass += masses[i];
}

// Remove center of mass motion
if (totalMass > 0.0) {
    comVelocity = comVelocity / totalMass;
    for (std::size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] -= comVelocity;
    }
}

// Scale velocities to match exact target temperature
double currentKE = 0.0;
for (std::size_t i = 0; i < velocities.size(); ++i) {
    currentKE += 0.5 * masses[i] * velocities[i].lengthSquared();
}

double targetKE = 1.5 * velocities.size() * kB * temperature;
if (currentKE > 0.0) {
    double scaleFactor = std::sqrt(targetKE / currentKE);
    for (std::size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] *= scaleFactor;
    }
}

